def solve(a, b):
    n, m = len(a), len(b)
    # ensure smaller dimension for space optimization
    if n < m:
        a, b = b, a
        n, m = m, n
    # now n >= m
    prev = list(range(m+1))
    for i in range(1, n+1):
        cur = [i] + [0]*m
        ai = a[i-1]
        for j in range(1, m+1):
            if ai == b[j-1]:
                cur[j] = prev[j-1]
            else:
                cur[j] = 1 + min(prev[j], cur[j-1], prev[j-1])
        prev = cur
    return prev[m]

