    """
    if not intervals:
        return []
    # Filter out invalid intervals (not length 2)
    cleaned = []
    for iv in intervals:
        if isinstance(iv, (list, tuple)) and len(iv) == 2:
            start, end = iv[0], iv[1]
            # Ensure numeric comparison; try to convert to int if possible
            try:
                start = int(start)
                end = int(end)
            except Exception:
                continue
            if start <= end:
                cleaned.append([start, end])
    if not cleaned:
        return []
    cleaned.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = cleaned[0]
    for start, end in cleaned[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged
