def solve(nums):
    # Return the length of the longest strictly increasing subsequence.
    # Use patience sorting (binary search) for O(n log n) time.
    if not isinstance(nums, list):
        try:
            nums = list(nums)
        except Exception:
            return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an LIS of length i+1
    for x in nums:
        # Find insertion point (first >= x) for strictly increasing, we need >
        # So use bisect_left on tails with x to replace first >= x.
        # For strictly increasing, we want to place x in position of first >= x.
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

